+							ClusterSpecifier: &v3routepb.RouteAction_Cluster{Cluster: clusterA},
+						}},
+					},
+					{
+						Match: &v3routepb.RouteMatch{
+							PathSpecifier: &v3routepb.RouteMatch_Prefix{Prefix: "/grpc.testing.TestService/EmptyCall"},
+						},
