+	// the matching header cleanly fall through.
+	if _, err := client.EmptyCall(ctx, &testpb.Empty{}); status.Code(err) != codes.OK {
+		t.Fatalf("EmptyCall() failed with status code %v, want OK", status.Code(err))
+	}
+}

