+func verifyServiceConfig(ctx context.Context, t *testing.T, jsonCh chan string, wantClusters ...string) {
+	t.Helper()
+	select {
+	case <-ctx.Done():
+		t.Fatal("Timeout waiting for resolver state update")
+	case js := <-jsonCh:
+		compareJSONConfigs(t, js, wantServiceConfig(wantClusters...))
+	}
+}
